package io.knowledgebrain.learning;
import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;import org.flywaydb.core.Flyway;import org.postgresql.ds.PGSimpleDataSource;import org.springframework.jdbc.core.JdbcTemplate;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_LEARNING_DATABASE_URL",matches=".+")
class GitHubEvidenceMigrationTest {
 @Test void upgradePreservesLegacyPinsKeysSessionAndWireAndNewOutboxFailureRollsBackEntireEvidence(){var ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_LEARNING_DATABASE_URL"));ds.setUser("brain_learning");ds.setPassword(System.getenv("BRAIN_TEST_LEARNING_DATABASE_PASSWORD"));var sql=new JdbcTemplate(ds);String schema="github_bundle_test_"+UUID.randomUUID().toString().replace("-","");assertTrue(schema.matches("github_bundle_test_[a-f0-9]{32}"));sql.execute("CREATE SCHEMA "+schema);try{ds.setCurrentSchema(schema);Flyway.configure().dataSource(ds).target("12").load().migrate();var clock=Clock.systemUTC();var ids=new UuidV7(clock);UUID space=ids.next(),actor=ids.next(),note=ids.next(),repo=ids.next(),commit=ids.next();String trace="b".repeat(32),key=UUID.randomUUID().toString().replace("-","");var roots=new RoadmapStore(ds,clock);var root=roots.create(space,actor,"Legacy root","",trace);root=roots.graph(space,root.roadmapId(),actor,1,new RoadmapGraph.Edit(List.of(new RoadmapGraph.NodeEdit("new:a","Legacy node","")),List.of()),trace);UUID roadmap=root.roadmapId(),node=root.nodes().getFirst().nodeId();var legacy=new LearningEvidenceStore(ds,clock,roots);var input=new LearningEvidenceStore.Input(node,note,1,"Legacy memo");var value=legacy.record(space,roadmap,actor,key,input,trace,()->new NoteReferenceClient.Reference(space,note,actor,1,"Legacy note","PRIVATE")).evidence();var study=new LearningStudyStore(ds,clock,roots);String end=clock.instant().minusSeconds(1800).toString(),start=Instant.parse(end).minusSeconds(60).toString();var session=study.record(space,roadmap,actor,UUID.randomUUID().toString().replace("-",""),new LearningStudyStore.Input(node,start,end,"Legacy session"),trace).session();var links=new EvidenceSessionStore(ds,clock,roots,study);var pinned=links.change(space,roadmap,value.evidenceId(),"NOTE",actor,0,new EvidenceSessionStore.Input(session.sessionId(),1L),trace);var before=sql.queryForList("SELECT id,encode(payload,'hex') AS wire FROM outbox_event ORDER BY id");var snapshot=sql.queryForList("SELECT snapshot::text FROM learning_evidence_revision ORDER BY revision_id");Flyway.configure().dataSource(ds).load().migrate();assertEquals(before,sql.queryForList("SELECT id,encode(payload,'hex') AS wire FROM outbox_event ORDER BY id"));assertEquals(snapshot,sql.queryForList("SELECT snapshot::text FROM learning_evidence_revision ORDER BY revision_id"));assertEquals(value,legacy.get(space,roadmap,value.evidenceId()));assertEquals(pinned,links.get(space,roadmap,value.evidenceId(),"NOTE"));assertFalse(legacy.record(space,roadmap,actor,key,input,trace,()->{fail();return null;}).created());var github=new GitHubEvidenceStore(ds,clock,roots);var ref=new GitHubReferenceClient.Reference(space,actor,repo,commit,"a/b","a".repeat(40),"subject",null,"2020-01-01T00:00:00Z","2026-10-01T00:00:00Z","https://github.com/a/b/commit/"+"a".repeat(40),"PRIVATE","PUBLIC",1);sql.execute("ALTER TABLE outbox_event ADD CONSTRAINT github_test_fail CHECK(aggregatetype<>'github-evidence')");assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->github.record(space,roadmap,actor,UUID.randomUUID().toString().replace("-",""),new GitHubEvidenceStore.Input(node,repo,commit,""),trace,()->ref));assertTrue(github.page(space,roadmap,"ACTIVE",null,20).items().isEmpty());assertEquals(snapshot,sql.queryForList("SELECT snapshot::text FROM learning_evidence_revision ORDER BY revision_id"));assertEquals(before,sql.queryForList("SELECT id,encode(payload,'hex') AS wire FROM outbox_event ORDER BY id"));sql.execute("ALTER TABLE outbox_event DROP CONSTRAINT github_test_fail");var created=github.record(space,roadmap,actor,UUID.randomUUID().toString().replace("-",""),new GitHubEvidenceStore.Input(node,repo,commit,"New GitHub memo"),trace,()->ref).evidence();assertEquals("GITHUB",links.change(space,roadmap,created.evidenceId(),"GITHUB",actor,0,new EvidenceSessionStore.Input(session.sessionId(),1L),trace).evidenceKind());assertEquals(13,sql.queryForObject("SELECT max(version::int) FROM flyway_schema_history WHERE success AND version IS NOT NULL",Integer.class));}finally{ds.setCurrentSchema("public");new JdbcTemplate(ds).execute("DROP SCHEMA "+schema+" CASCADE");}}
}
